(1055, 1, '2021-11-19 09:45:06', '2021-11-19 12:45:06', '<!-- wp:cms-adm/title-text {\"title\":[\"Marca Oficial Municipais\"],\"description\":[\"\"]} -->\n<div class=\"wp-block-cms-adm-title-text text-data-block\"><div class=\"title-text-block\"><h2>Marca Oficial Municipais</h2><label></label></div></div>\n<!-- /wp:cms-adm/title-text -->\n\n<!-- wp:cms-adm/date-title-link-file-upload {\"caption\":\"Lei de Construção e Identidade Visual - 2018\",\"title\":[\"Lei 660 1972 - Sobre a Construção da Identidade Visual do Municipio de Toledo\",\"Manual de Marca - Logo do Governo Municipal de Toledo - 2018\"],\"url\":[\"https://novosite.toledo.pr.gov.br/wp-content/uploads/2021/11/lei_660-1972_-_dispoe_sobre_a_forma_e_a_apresentacao_dos_simbolos_do_municipio_de_toledo_e_da_outras_providencias.pdf\",\"https://novosite.toledo.pr.gov.br/wp-content/uploads/2021/11/manual_marca_governo_municipal_2018.pdf\"],\"date_link\":[\"17/11/2021\",\"17/11/2021\"],\"mime_type\":[\"pdf\",\"pdf\"]} -->\n<table class=\"wp-block-cms-adm-date-title-link-file-upload table-link-box  table table-striped table-bordered\"><caption><label>Lei de Construção e Identidade Visual - 2018</label><i class=\"fas fa-chevron-up\"></i></caption><thead><tr><td>Data</td><td>Documento</td><td>Visualizar</td><td>Baixar</td></tr></thead><tbody><tr><td>17/11/2021</td><td>Lei 660 1972 - Sobre a Construção da Identidade Visual do Municipio de Toledo</td><td class=\"btn-exibir\"><a href=\"https://novosite.toledo.pr.gov.br/wp-content/uploads/2021/11/lei_660-1972_-_dispoe_sobre_a_forma_e_a_apresentacao_dos_simbolos_do_municipio_de_toledo_e_da_outras_providencias.pdf\" style=\"color:inherit\"><button class=\"btn-tab\"><i class=\"fa fa-search\"></i></button></a></td><td class=\"btn-exibir\"><a href=\"/download.php?file=/wp-content/uploads/2021/11/lei_660-1972_-_dispoe_sobre_a_forma_e_a_apresentacao_dos_simbolos_do_municipio_de_toledo_e_da_outras_providencias.pdf\" style=\"color:inherit\"><button class=\"btn-tab mime-types\"><i