(1180, 1, '2021-11-19 17:09:20', '2021-11-19 20:09:20', '<!-- wp:cms-adm/slide-show {\"url\":[\"https://novosite.toledo.pr.gov.br/wp-content/uploads/2021/11/porque_revisar_o_plano_diretor-2.png\"],\"title\":[\"0123456789012345678901234567890123456789\"],\"description\":[\"\\u003cp\\u003e01234567890123456789012345678901234567890123456789\\u003c/p\\u003e\",\"\"]} -->\n<div class=\"wp-block-cms-adm-slide-show w-100 slide-show-block\"><div id=\"carouselExampleInterval0\" class=\"carousel slide mx-auto\" style=\"width:80%;padding-top:50%;min-width:280px;margin-bottom:calc(170px - 6vw)\" data-bs-ride=\"carousel\"><div class=\"carousel-indicators\"><button type=\"button\" data-bs-target=\"#carouselExampleInterval0\" data-bs-slide-to=\"0\" class=\"active\" aria-current=\"true\" aria-label=\"0123456789012345678901234567890123456789 \"></button></div><div class=\"carousel-inner\" style=\"height:100%;width:100%;position:absolute;top:0px;overflow:visible\"><div class=\"carousel-item rounded active\" style=\"width:100%;height:100%;background-image:url(https://novosite.toledo.pr.gov.br/wp-content/uploads/2021/11/porque_revisar_o_plano_diretor-2.png);background-size:Cover;background-position:center center\"><div class=\"carousel-caption color-1 w-100\" style=\"top:calc(100% - 25px);right:10px;left:auto\"><h4 class=\"color-1 w-100 text-end text-break\" style=\"text-shadow: 2px 2px 10px #000000\">0123456789012345678901234567890123456789</h4><div class=\"color-1 w-100 text-end text-break\" style=\"color:white;text-shadow: 2px 2px 10px #000000;background-color:inherit\"><p>01234567890123456789012345678901234567890123456789</p></div></div></div></div><button class=\"carousel-control-prev\" data-bs-target=\"#carouselExampleInterval0\" data-bs-slide=\"prev\"><spam class=\"carousel-control-prev-icon\" aria-hidden=\"true\"></spam></button><button class=\"carousel-control-next\" data-bs-target=\"#carouselExampleInterval0\" data-bs-slide=\"next\"><spam class=\"carousel-control-next-icon\" ar