INSERT INTO `toledoposts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(2068, 1, '2021-12-01 09:45:10', '2021-12-01 12:45:10', '<!-- wp:cms-adm/topic-title-text {\"title\":[\"O que é?\",\"A quem se destina?\",\"Como acessar?\"],\"description\":[\"\\u003cp\\u003eDescrever sobre  o que é o conselho de forma simples\\u003c/p\\u003e\",\"\\u003cp\\u003eDescrever a quem se destina o conselho de forma simples\\u003c/p\\u003e\",\"\\u003cp\\u003eInformações para contato\\u003c/p\\u003e\"]} -->\n<div class=\"wp-block-cms-adm-topic-title-text topic-text-block\"><div class=\"text-block\"><h4>O que é?</h4><label><p>Descrever sobre  o que é o conselho de forma simples</p></label></div><div class=\"text-block\"><h4>A quem se destina?</h4><label><p>Descrever a quem se destina o conselho de forma simples</p></label></div><div class=\"text-block\"><h4>Como acessar?</h4><label><p>Informações para contato</p></label></div></div>\n<!-- /wp:cms-adm/topic-title-text -->\n\n<!-- wp:cms-adm/topic-title-text {\"title\":[\"Endereço\",\"Telefone\",\"E-mail:\"],\"description\":[\"\\u003cp\\u003eRua Dr. Cyro Fernandes do Lago, nº 167, Vila Pioneiro. Toledo-PR\\u003c/p\\u003e\",\"\\u003cp\\u003e3378-8604\\u003c/p\\u003e\",\"\\u003cp\\u003ecmastoledopr@yahoo.com.br\\u003c/p\\u003e\"]} -->\n<div class=\"wp-block-cms-adm-topic-title-text topic-text-block\"><div class=\"text-block\"><h4>Endereço</h4><label><p>Rua Dr. Cyro Fernandes do Lago, nº 167, Vila Pioneiro. Toledo-PR</p></label></div><div class=\"text-block\"><h4>Telefone</h4><label><p>3378-8604</p></label></div><div class=\"text-block\"><h4>E-mail:</h4><label><p>cmastoledopr@yahoo.com.br</p></label></div></div>\n<!-- /wp:cms-adm/topic-title-text -->\n\n<!-- wp:cms-adm/topic-title-text {\"title\":[\"Legislação\"],\"description\":[\"\\u003cp\\u003eO Conselho Municipal de Assistência Social (CMAS), instituído pela Lei nº 1.781/1995 \\u003cem\\u003e(alterada pela lei 2003 de 16/07/2009) \\u003c/em\\u003eé mantido como órgão normativo, deliberativo, controlador e fiscalizador das ações de Assistência Social no Município de Toledo, e reestruturado na forma desta Lei.  O Conselho Municipal de Assistência Social é composto por 56 membros (28 titulares e 28 suplentes), sendo 50% de representantes do poder público (Secretaria de Assistência Social, Agropecuária e Abastecimento, Atendimento à Mulher, Cultura, Educação, Fazenda,  Saúde, Esporte e Lazer, Meio Ambiente, 20ª Reginal de Saúde, Unioeste, Núcleo Regional de Educação) e 50% de representantes da sociedade civil (organizações dos trabalhadores do setor da política de assistência social, inclusive sindicatos da área, legalmente constituídos; usuários da política de assistência social; entidades prestadoras de serviços de proteção social básica, legalmente constituídos; entidades prestadoras de serviços de proteção social especial de média e alta complexidade). \\u003c/p\\u003e\\u003cp\\u003e\\u003c/p\\u003e\\u003cp\\u003eP\\u003cstrong\\u003eresidente do CMAS\\u003c/strong\\u003e: Rachel Lucia Hech\\u003c/p\\u003e\\u003cp\\u003e\\u003cstrong\\u003eVice-Presidente do CMAS\\u003c/strong\\u003e: Jaqueline Fernanda Machado\\u003c/p\\u003e\\u003cp\\u003e\\u003cstrong\\u003eSecretária Executiva: \\u003c/strong\\u003eMarlene Duderstadt\\u003c/p\\u003e\\u003cp\\u003e\\u003c/p\\u003e\"]} -->\n<div class=\"wp-block-cms-adm-topic-title-text topic-text-block\"><div class=\"text-block\"><h4>Legislação</h4><label><p>O Conselho Municipal de Assistência Social (CMAS), instituído pela Lei nº 1.781/1995 <em>(alterada pela lei 2003 de 16/07/2009) </em>é mantido como órgão normativo, deliberativo, controlador e fiscalizador das ações de Assistência Social no Município de Toledo, e reestruturado na forma desta Lei.  O Conselho Municipal de Assistência Social é composto por 56 membros (28 titulares e 28 suplentes), sendo 50% de representantes do poder público (Secretaria de Assistência Social, Agropecuária e Abastecimento, Atendimento à Mulher, Cultura, Educação, Fazenda,  Saúde, Esporte e Lazer, Meio Ambiente, 20ª Reginal de Saúde, Unioeste, Núcleo Regional de Educação) e 50% de representantes da sociedade civil (organizações dos trabalhadores do setor da política de assistência social, inclusive sindicatos da área, legalmente constituídos; usuários da política de assistência social; entidades prestadoras de serviços de proteção social básica, legalmente constituídos; entidades prestadoras de serviços de proteção social especial de média e alta complexidade). </p><p></p><p>P<strong>residente do CMAS</strong>: Rachel Lucia Hech</p><p><strong>Vice-Presidente do CMAS</strong>: Jaqueline Fernanda Machado</p><p><strong>Secretária Executiva: </strong>Marlene Duderstadt</p><p></p></label></div></div>\n<!-- /wp:cms-adm/topic-title-text -->\n\n<!-- wp:cms-adm/title-text {\"title\":[\"As reuniões acontecem mensalmente na Secretaria de Assistência Social \"],\"description\":[\"*conforme calendário anexo abaixo. (reuniões ordinárias sempre na primeira quarta-feira do mês)\"]} -->\n<div class=\"wp-block-cms-adm-title-text text-data-block\"><div class=\"title-text-block\"><h2>As reuniões acontecem mensalmente na Secretaria de Assistência Social </h2><label class=\"text-center\">*conforme calendário anexo abaixo. (reuniões ordinárias sempre na primeira quarta-feira do mês)</label></div></div>\n<!-- /wp:cms-adm/title-text -->\n\n<!-- wp:cms-adm/date-title-link-file-upload {\"caption\":\"Calendário - 2021\",\"title\":[\"Calendario 2021.pdf\"],\"url\":[\"https://novosite.toledo.pr.gov.br/wp-content/uploads/2021/11/Calendario.pdf\"],\"date_link\":[\"25/11/2021\"],\"mime_type\":[\"pdf\"]} -->\n<table class=\"wp-block-cms-adm-date-title-link-file-upload table-link-box  table table-striped table-bordered\"><caption><label>Calendário - 2021</label><i class=\"fas fa-chevron-up\"></i></caption><thead><tr><td>Data</td><td class=\"description\">Documento</td><td class=\"btn-exibir\">Visualizar</td><td class=\"btn-exibir\">Baixar</td></tr></thead><tbody><tr><td>25/11/2021</td><td class=\"description\">Calendario 2021.pdf</td><td class=\"