(2103, 1, '2021-12-01 10:03:25', '2021-12-01 13:03:25', '<!-- wp:cms-adm/destack-buttons {\"title\":[\"\\u003cp\\u003eHotel\\u003c/p\\u003e\",\"\\u003cp\\u003eMotel\\u003c/p\\u003e\",\"\\u003cp\\u003eHostel\\u003c/p\\u003e\",\"\\u003cp\\u003ePousada\\u003c/p\\u003e\",\"\\u003cp\\u003eChalé\\u003c/p\\u003e\",\"\\u003cp\\u003ePensão\\u003c/p\\u003e\",\"\\u003cp\\u003eQuiosques\\u003c/p\\u003e\",\"\\u003cp\\u003eAluguel\\u003c/p\\u003e\"],\"url\":[\"\",\"\",\"\",\"\",\"\",\"\",\"\",\"\"],\"logo\":[\"\",\"\",\"\",\"\",\"\"]} -->\n<div class=\"wp-block-cms-adm-destack-buttons  destack-buttons-block\"><a class=\"destack-buttons text-decoration-none\" href=\"\"><img src=\"https://novosite.toledo.pr.gov.br/wp-content/themes/cityhalltoledo/images/logotoledo.png\"/><div class=\"txt\"><p>Hotel</p></div></a><a class=\"destack-buttons text-decoration-none\" href=\"\"><img src=\"https://novosite.toledo.pr.gov.br/wp-content/themes/cityhalltoledo/images/logotoledo.png\"/><div class=\"txt\"><p>Motel</p></div></a><a class=\"destack-buttons text-decoration-none\" href=\"\"><img src=\"https://novosite.toledo.pr.gov.br/wp-content/themes/cityhalltoledo/images/logotoledo.png\"/><div class=\"txt\"><p>Hostel</p></div></a><a class=\"destack-buttons text-decoration-none\" href=\"\"><img src=\"https://novosite.toledo.pr.gov.br/wp-content/themes/cityhalltoledo/images/logotoledo.png\"/><div class=\"txt\"><p>Pousada</p></div></a><a class=\"destack-buttons text-decoration-none\" href=\"\"><img src=\"https://novosite.toledo.pr.gov.br/wp-content/themes/cityhalltoledo/images/logotoledo.png\"/><div class=\"txt\"><p>Chalé</p></div></a><a class=\"destack-buttons text-decoration-none\" href=\"\"><img src=\"https://novosite.toledo.pr.gov.br/wp-content/themes/cityhalltoledo/images/logotoledo.png\"/><div class=\"txt\"><p>Pensão</p></div></a><a class=\"destack-buttons text-decoration-none\" href=\"\"><img src=\"https://novosite.toledo.pr.gov.br/wp-content/themes/cityhalltoledo/images/logotoledo.png\"/><div class=\"txt\"><p>Quiosques</p></div></a><a class=\"destack-buttons text-decoration-none\" href=\"\"><img src=\"https://novosite.toledo.pr.gov.br/wp-content/themes/cityhalltoledo/images/logotoledo.png\"/><div class=\"txt\"><p>Aluguel</p></div></a></div>\n<!-- /wp:cms-adm/destack-buttons -->\n\n<!-- wp:cms-adm/separator -->\n<div class=\"wp-block-cms-adm-separator separator-green\"></div>\n<!-- /wp:cms-adm/separator -->\n\n<!-- wp:cms-adm/title-text {\"title\":[\"Festa Regional (ser caixa alta)\",\"(BUSCA) Campo de busca no sistema\"],\"description\":[\"\",\"centralizar este campo no \\u0022titulo\\u0022 - O sistema deve funcionar para inserir e remover comércios e ajudar a fazer o sitema de busca do mesmo\"]} -->\n<div class=\"wp-block-cms-adm-title-text text-data-block\"><div class=\"title-text-block\"><h2>Festa Regional (ser caixa alta)</h2><label class=\"text-center\"></label></div><div class=\"title-text-block\"><h2>(BUSCA) Campo de busca no sistema</h2><label class=\"text-center\">centralizar este campo no \"titulo\" - O sistema deve funcionar para inserir e remover comércios e ajudar a fazer o sitema de busca do mesmo</label></div></div>\n<!-- /wp:cms-adm/title-text -->', 'Hotelaria', '', 'inherit', 'closed', 'closed', '', '906-revision-v1', '', '', '2021-12-01 10:03:25', '2021-12-01 13:03:25', '', 906, 'https://novosite.toledo.pr.gov.br/?p=2103', 0, 'revision', '', 0);
