60;ESTE&#160;&#160;SEJA&#160;&#160;UM&#160;&#160;DOS&#160;&#160;MOTIVOS&#160;\nPELO&#160;QUAL&#160;O&#160;íNDICE&#160;DE&#160;ANALFABETISMO&#160;EM&#160;TOLEDO&#160;E&#160;MAL.C.RONDON&#160;E&#160;NA&#160;REGIãO&#160;DA&#160;ANTIGA&#160;\nFAZENDA&#160;\nBRITâNIA,&#160;\né&#160;\nPROPORCIONALMENTE&#160;\nBEM&#160;\nABAIXO&#160;\nDO&#160;\nDE&#160;\nOUTRAS&#160;\nCIDADES”.(NIEDERAUER,&#160;2004,&#160;P.&#160;253).&#160;\n&#160;\n&#160;\n&#160;\n\n\n\n\n\n\n\n[130]&#160;\n&#160;\nLINHA DO&#160;TEMPO&#160;DA HISTÓRIA DA EDUCAÇÃO&#160;DO&#160;MUNICÍPIO&#160;DE TOLEDO:&#160;\n1938&#160;&#160;–&#160;&#160;INíCIO&#160;&#160;DAS&#160;&#160;ATIVIDADES&#160;&#160;DA&#160;&#160;ESCOLA&#160;&#160;ISOLADA&#160;&#160;DO&#160;&#160;RIO&#160;&#160;BRANCO,&#160;&#160;PRóXIMO&#160;&#160;AO&#160;&#160;PORTO&#160;BRITâNIA;&#160;\n1948&#160;–&#160;CRIADA&#160;1ª&#160;ESCOLA&#160;DA&#160;ENTãO&#160;VILA&#160;TOLEDO;&#160;\n1953&#160;–&#160;TOLEDO&#160;CONTA&#160;COM&#160;19&#160;ESCOLAS,&#160;DAS&#160;QUAIS&#160;17&#160;NO&#160;INTERIOR&#160;E&#160;DUAS&#160;NA&#160;SEDE,&#160;COM&#160;O&#160;TOTAL&#160;DE&#160;23&#160;PROFESSORES;&#160;\n1956&#160;&#160;–&#160;&#160;SãO&#160;&#160;38&#160;&#160;AS&#160;&#160;ESCOLAS&#160;&#160;MUNICIPAIS&#160;&#160;E&#160;&#160;2&#160;&#160;PARTICULARES,&#160;&#160;COM&#160;&#160;1725&#160;&#160;ALUNOS&#160;&#160;E&#160;&#160;50&#160;PROFESSORES;&#160;\n1958&#160;–&#160;INSTALADA&#160;EM&#160;TOLEDO PRIMEIRA&#160;ESCOLA&#160;ESTADUAL:&#160;LUIZ&#160;AUGUSTO MORAIS&#160;REGO;&#160;\n1960&#160;–&#160;INSTALADA&#160;A&#160;INSPETORIA&#160;REGIONAL&#160;DE&#160;ENSINO,&#160;óRGãO&#160;ESTADUAL&#160;DE&#160;ENSINO;&#160;\n1967-&#160;FUNDADA&#160;A&#160;UNIãO TOLEDANA&#160;DE&#160;ESTUDANTES&#160;DE&#160;1º&#160;E&#160;2º&#160;GRAU&#160;(UTES);&#160;\n1973-&#160;CRIADA&#160;A&#160;SECRETARIA MUNICIPAL&#160;DE&#160;EDUCAçãO E&#160;CULTURA;&#160;\n1974-&#160;CRIADA&#160;A&#160;FUNDAçãO EDUCACIONAL&#160;DE&#160;TOLEDO (FUNET);&#160;\n1980&#160;&#160;–&#160;&#160;